function typeformEventFeedback({ response, questionTitle }) {
  if (!response || !Array.isArray(response.answers) || !Array.isArray(response.definition?.fields))
    throw new Error("Expected a complete Typeform response");
  if (typeof questionTitle !== "string" || !questionTitle.trim())
    throw new Error("Configure the feedback question title");
  const fields = response.definition.fields.filter((field) => field?.title === questionTitle);
  if (
    fields.length !== 1 ||
    typeof fields[0].id !== "string" ||
    !fields[0].id ||
    response.definition.fields.filter((field) => field?.id === fields[0].id).length !== 1
  )
    throw new Error("The feedback question title must identify one field");
  const answers = response.answers.filter((answer) => answer?.field?.id === fields[0].id);
  if (
    answers.length !== 1 ||
    answers[0].type !== "text" ||
    typeof answers[0].text !== "string" ||
    !answers[0].text.trim()
  )
    throw new Error("One nonblank text feedback answer is required");
  return { feedback: answers[0].text };
}

return $input.all().flatMap((item, index) =>
  item.json.event_type === "form_response"
    ? [
        {
          json: typeformEventFeedback({
            response: item.json.form_response,
            questionTitle: "What did you think about the event?",
          }),
          pairedItem: { item: index },
        },
      ]
    : [],
);

function comprehendFeedbackDecision({ assessment, feedback }) {
  if (
    !assessment ||
    typeof assessment !== "object" ||
    Array.isArray(assessment) ||
    !["POSITIVE", "NEGATIVE", "NEUTRAL", "MIXED"].includes(assessment.Sentiment)
  )
    throw new Error("Comprehend did not return a valid sentiment");
  for (const name of ["Positive", "Negative", "Neutral", "Mixed"]) {
    const score = assessment.SentimentScore?.[name];
    if (typeof score !== "number" || !Number.isFinite(score) || score < 0 || score > 1)
      throw new Error("Comprehend did not return a valid " + name + " confidence");
  }
  if (typeof feedback !== "string" || !feedback.trim())
    throw new Error("Original feedback text is missing");
  return {
    assessment,
    negative: assessment.Sentiment === "NEGATIVE",
    message:
      "You got new feedback with a score of " +
      assessment.SentimentScore.Negative +
      ". Here is what it says:" +
      feedback,
  };
}

return {
  json: comprehendFeedbackDecision({
    assessment: $json,
    feedback: $("Read the event feedback answer").first().json.feedback,
  }),
};

function mattermostFeedbackPosted({ post, assessment }) {
  if (
    !post ||
    typeof post !== "object" ||
    Array.isArray(post) ||
    typeof post.id !== "string" ||
    !post.id.trim()
  )
    throw new Error("Mattermost did not return a saved post ID");
  return { posted: true, assessment, post };
}

return {
  json: mattermostFeedbackPosted({
    post: $json,
    assessment: $("Check the returned sentiment").first().json.assessment,
  }),
};

function negativeFeedbackSkipped({ assessment }) {
  return { posted: false, assessment, post: null };
}

return { json: negativeFeedbackSkipped({ assessment: $json.assessment }) };
